<?php $page='password';require __DIR__.'/_head.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$a=db()->prepare('SELECT password_hash FROM admins WHERE id=?');$a->execute([$_SESSION['admin_id']]);$a=$a->fetch();if(!password_verify($_POST['current']??'',$a['password_hash']))throw new RuntimeException('Current password is incorrect.');if(strlen($_POST['new']??'')<8)throw new RuntimeException('New password must be at least 8 characters.');db()->prepare('UPDATE admins SET password_hash=? WHERE id=?')->execute([password_hash($_POST['new'],PASSWORD_DEFAULT),$_SESSION['admin_id']]);$msg='Password changed successfully.';}catch(Throwable $e){$msg=$e->getMessage();}}?><div class="topbar"><h1>Change Password</h1></div><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Current password<input type="password" name="current" required></label><label>New password<input type="password" name="new" minlength="8" required></label><button class="btn primary">Update password</button></form></div><?php require __DIR__.'/_foot.php';
